def get_company(nif, **_extra):
    import json, os, datetime, re, time, unicodedata, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0410000" if __import__("os").path.isdir("./environment_mix/0410000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        # deterministic enough for offline store
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{int(time.time()*1000)}"

    def _normalize_text(s):
        if s is None:
            return ""
        s = str(s)
        s = unicodedata.normalize("NFKD", s)
        s = "".join(ch for ch in s if not unicodedata.combining(ch))
        s = s.lower()
        out = []
        prev_space = False
        for ch in s:
            if ch.isalnum():
                out.append(ch)
                prev_space = False
            else:
                if not prev_space:
                    out.append(" ")
                    prev_space = True
        return " ".join("".join(out).split()).strip()

    def _pick_authenticated_client(clients):
        # Ambient auth: select any active client that can serve calls.
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        # Prefer the one with the highest quotas (more likely to allow call).
        def _quota_key(c):
            qd = c.get("quota_requests_per_day")
            qm = c.get("quota_requests_per_minute")
            try:
                qd = int(qd)
            except Exception:
                qd = 0
            try:
                qm = int(qm)
            except Exception:
                qm = 0
            return (qd, qm)
        active.sort(key=_quota_key, reverse=True)
        return active[0]

    def _enforce_rate_limit_and_log(tool_name, client, input_nif=None, input_name=None, input_city=None,
                                    matched_company_id=None, result_count=0, status="ok",
                                    latency_ms=None, error_code=None, override_status=None):
        # Writes search_requests row, enforcing quotas first. Returns (allowed:bool, error_obj or None).
        search_requests = _load("search_requests.json")
        now = _now()

        def _count_within(seconds):
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=seconds)
            cnt = 0
            for r in search_requests:
                if not isinstance(r, dict):
                    continue
                if r.get("client_id") != client.get("id"):
                    continue
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    # Parse ISO Z
                    if ts.endswith("Z"):
                        ts2 = ts[:-1]
                    else:
                        ts2 = ts
                    dt = datetime.datetime.fromisoformat(ts2)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
            return cnt

        # Validate quota fields
        try:
            q_day = int(client.get("quota_requests_per_day"))
            q_min = int(client.get("quota_requests_per_minute"))
        except Exception:
            q_day = 0
            q_min = 0

        if q_day < 0 or q_min < 0:
            q_day = max(q_day, 0)
            q_min = max(q_min, 0)

        minute_count = _count_within(60)
        day_count = _count_within(86400)

        limited = (minute_count >= q_min) or (day_count >= q_day)
        final_status = "rate_limited" if limited else status
        if override_status is not None:
            final_status = override_status

        req_row = {
            "id": _new_id("sr"),
            "client_id": client.get("id"),
            "tool_name": tool_name,
            "input_nif": input_nif,
            "input_name": input_name,
            "input_city": input_city,
            "matched_company_id": matched_company_id,
            "result_count": int(result_count) if isinstance(result_count, int) else 0,
            "status": final_status,
            "latency_ms": latency_ms if (latency_ms is None or (isinstance(latency_ms, int) and latency_ms >= 0)) else None,
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        search_requests.append(req_row)
        _save("search_requests.json", search_requests)

        if limited:
            return False, _err("QUOTA_EXCEEDED", "Request quota exceeded.")
        return True, None

    t0 = time.time()

    # Input validation
    if not isinstance(nif, str) or not re.fullmatch(r"^[0-9]{9}$", nif or ""):
        clients = _load("api_clients.json")
        client = _pick_authenticated_client(clients)
        latency = int((time.time() - t0) * 1000)
        if client is not None:
            # log invalid input (even if later would be limited; business rule: invalid_input log)
            _enforce_rate_limit_and_log(
                "get_company", client, input_nif=nif if isinstance(nif, str) else None,
                result_count=0, status="invalid_input", latency_ms=latency
            )
        return _err("VALIDATION_ERROR", "Invalid NIF. Expected a 9-digit string.", field="nif")

    clients = _load("api_clients.json")
    client = _pick_authenticated_client(clients)
    if client is None:
        # No active client can serve.
        return _err("UNAUTHORIZED", "No active API client available.")

    if client.get("status") != "active":
        latency = int((time.time() - t0) * 1000)
        _enforce_rate_limit_and_log(
            "get_company", client, input_nif=nif, result_count=0, status="error",
            latency_ms=latency, error_code="CLIENT_NOT_ACTIVE"
        )
        return _err("UNAUTHORIZED", "API client is not active.")

    # Enforce quota before executing
    latency = int((time.time() - t0) * 1000)
    allowed, quota_err = _enforce_rate_limit_and_log(
        "get_company", client, input_nif=nif, result_count=0, status="ok",
        latency_ms=None  # set later by updating? Spec doesn't require update; we log once with best-effort latency after work below.
    )
    if not allowed:
        return quota_err

    companies = _load("companies.json")

    # Enforce uniqueness of nif among non-deleted: if duplicates exist, treat as conflict
    matches = [c for c in companies if isinstance(c, dict) and c.get("nif") == nif and c.get("record_status") != "deleted"]
    if len(matches) > 1:
        # log error with rate already consumed; append another log entry for observability
        latency = int((time.time() - t0) * 1000)
        _enforce_rate_limit_and_log(
            "get_company", client, input_nif=nif, matched_company_id=matches[0].get("id"),
            result_count=0, status="error", latency_ms=latency, error_code="DUPLICATE_NIF"
        )
        return _err("CONFLICT", "Multiple company records exist for the same NIF.", nif=nif)

    if not matches:
        latency = int((time.time() - t0) * 1000)
        _enforce_rate_limit_and_log(
            "get_company", client, input_nif=nif, result_count=0, status="not_found",
            latency_ms=latency
        )
        return _err("NOT_FOUND", "Company not found for provided NIF.", nif=nif)

    company = matches[0]

    latency = int((time.time() - t0) * 1000)
    _enforce_rate_limit_and_log(
        "get_company", client, input_nif=nif, matched_company_id=company.get("id"),
        result_count=1, status="ok", latency_ms=latency
    )

    return {"company": company}

