def search_companies_by_name_and_city(name, city, **_extra):
    import json, os, datetime, time, unicodedata, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0410000" if __import__("os").path.isdir("./environment_mix/0410000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _normalize(s):
        if s is None:
            return ""
        if not isinstance(s, str):
            s = str(s)
        s = s.strip().lower()
        s = unicodedata.normalize("NFKD", s)
        s = "".join(ch for ch in s if not unicodedata.combining(ch))
        s = re.sub(r"[^a-z0-9]+", " ", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _gen_id(prefix):
        # stable-ish, collision-resistant, matches existing id style (prefix + random)
        return f"{prefix}_{secrets.token_hex(10)}"

    def _ensure_list(x):
        return x if isinstance(x, list) else ([] if x is None else [])

    def _pick_active_client(clients):
        # Ambient auth: pick a client that can serve requests (active). Never require api_key.
        active = [c for c in _ensure_list(clients) if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        # Prefer a client with the highest quotas to reduce accidental rate-limit.
        def _q(c):
            try:
                return (int(c.get("quota_requests_per_day", 0)), int(c.get("quota_requests_per_minute", 0)))
            except Exception:
                return (0, 0)
        active.sort(key=_q, reverse=True)
        return active[0]

    def _parse_iso_z(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s = s.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt.replace(microsecond=0)
        except Exception:
            return None

    def _log_request(search_requests, client_id, status, result_count, matched_company_id=None, error_code=None, latency_ms=None):
        rid = _gen_id("nifc_req")
        row = {
            "id": rid,
            "client_id": client_id,
            "tool_name": "search_companies_by_name_and_city",
            "input_nif": None,
            "input_name": name if isinstance(name, str) else (None if name is None else str(name)),
            "input_city": city if isinstance(city, str) else (None if city is None else str(city)),
            "matched_company_id": matched_company_id,
            "result_count": int(result_count) if isinstance(result_count, int) and result_count >= 0 else 0,
            "status": status,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, int) and latency_ms >= 0 else None,
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        search_requests.append(row)
        return row

    def _rate_limited(search_requests, client):
        # Enforce per-minute and per-rolling-day quotas based on existing logs for this client.
        # Count all statuses (including rate_limited) as real backends often do; conservative.
        cid = client.get("id")
        qd = client.get("quota_requests_per_day", 0)
        qm = client.get("quota_requests_per_minute", 0)
        try:
            qd = int(qd)
        except Exception:
            qd = 0
        try:
            qm = int(qm)
        except Exception:
            qm = 0
        if qd < 0 or qm < 0:
            # schema says >=0; treat as validation error in client config -> block
            return True, "QUOTA_CONFIG_INVALID"

        day_ago = now - datetime.timedelta(days=1)
        min_ago = now - datetime.timedelta(minutes=1)

        day_count = 0
        min_count = 0
        for r in _ensure_list(search_requests):
            if not isinstance(r, dict) or r.get("client_id") != cid:
                continue
            dt = _parse_iso_z(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                day_count += 1
            if dt >= min_ago:
                min_count += 1

        if qm and min_count >= qm:
            return True, "quota_requests_per_minute"
        if qd and day_count >= qd:
            return True, "quota_requests_per_day"
        return False, None

    # Load datastore
    clients = _load("api_clients.json")
    companies = _load("companies.json")
    search_requests = _load("search_requests.json")

    client = _pick_active_client(clients)
    if client is None:
        # No active client exists anywhere -> UNAUTHORIZED; still log if possible? can't without client_id.
        return _err("UNAUTHORIZED", "No active API client available to serve this request.")

    # Validate input
    if not isinstance(name, str) or not name.strip():
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "invalid_input", 0, matched_company_id=None, error_code="name_required", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "Invalid input: name must be a non-empty string.", field="name")
    if not isinstance(city, str) or not city.strip():
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "invalid_input", 0, matched_company_id=None, error_code="city_required", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "Invalid input: city must be a non-empty string.", field="city")

    # Quota / client status enforcement
    if client.get("status") != "active":
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "rate_limited", 0, matched_company_id=None, error_code="client_not_active", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("UNAUTHORIZED", "API client is not active.", client_id=client.get("id"), client_status=client.get("status"))

    limited, which = _rate_limited(search_requests, client)
    if limited:
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "rate_limited", 0, matched_company_id=None, error_code=which, latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("QUOTA_EXCEEDED", "Quota exceeded.", client_id=client.get("id"), limit=which)

    # Search logic: case/diacritic-insensitive matching against normalized_name and city
    qname = _normalize(name)
    qcity = _normalize(city)
    results = []
    for c in _ensure_list(companies):
        if not isinstance(c, dict):
            continue
        if c.get("record_status") == "deleted":
            continue
        cname = c.get("normalized_name") or _normalize(c.get("legal_name", ""))
        ccity = _normalize(c.get("city", ""))
        # "matching" is flexible: allow substring containment for both fields
        if qname and cname and qname in _normalize(cname):
            if qcity and (qcity in ccity or ccity in qcity or (qcity and ccity and qcity == ccity)):
                results.append(c)

    # Sort: best match first (exact city + name prefix + shorter name), then stable by id
    def _score(c):
        cname = _normalize(c.get("normalized_name") or c.get("legal_name", ""))
        ccity = _normalize(c.get("city", ""))
        exact_city = 1 if ccity == qcity else 0
        name_prefix = 1 if cname.startswith(qname) else 0
        return (-exact_city, -name_prefix, len(cname), c.get("id", ""))
    results.sort(key=_score)

    latency_ms = int((time.time() - t0) * 1000)
    if not results:
        _log_request(search_requests, client.get("id"), "not_found", 0, matched_company_id=None, latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        # Per tool description: NOT_FOUND when no companies match
        return _err("NOT_FOUND", "No companies match the provided name and city.", name=name, city=city)

    _log_request(search_requests, client.get("id"), "ok", len(results), matched_company_id=results[0].get("id"), latency_ms=latency_ms)
    _save("search_requests.json", search_requests)

    return {
        "companies": results,
        "count": len(results),
    }

def whoami(api_key, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0410000" if __import__("os").path.isdir("./environment_mix/0410000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.urandom(4).hex()}"

    # Validate input type
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.")

    clients = _load("api_clients.json")
    requests = _load("search_requests.json")

    # Authenticate: accept either direct stored api_key_hash value OR id (client id)
    # Also try common hash encodings of the provided api_key to match stored api_key_hash.
    key = api_key.strip()
    candidates = []
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == key or c.get("api_key_hash") == key:
            candidates.append(c)

    if not candidates:
        # Try hashing if store kept sha256/sha1/md5
        digests = set()
        digests.add(hashlib.sha256(key.encode("utf-8")).hexdigest())
        digests.add(hashlib.sha1(key.encode("utf-8")).hexdigest())
        digests.add(hashlib.md5(key.encode("utf-8")).hexdigest())
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("api_key_hash") in digests:
                candidates.append(c)

    if not candidates:
        return _err("UNAUTHORIZED", "Invalid API key.")

    # If multiple, prefer active
    candidates.sort(key=lambda c: (c.get("status") == "active", c.get("updated_at") or ""), reverse=True)
    client = candidates[0]

    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active.", client_status=client.get("status"))

    now = datetime.datetime.utcnow()
    day_ago = now - datetime.timedelta(days=1)
    min_ago = now - datetime.timedelta(minutes=1)

    day_used = 0
    min_used = 0
    for r in requests:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client.get("id"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            continue
        if dt >= day_ago:
            day_used += 1
        if dt >= min_ago:
            min_used += 1

    qd = client.get("quota_requests_per_day")
    qm = client.get("quota_requests_per_minute")
    try:
        qd = int(qd)
        qm = int(qm)
    except Exception:
        qd = 0
        qm = 0

    # Log whoami call in search_requests for observability (tool_name enum does not include whoami).
    # We must not write invalid enum values into search_requests. Therefore: do not log here.
    # (Schema restricts tool_name; forcing it would corrupt datastore.)
    # Return identity info.
    return {
        "client": {
            "id": client.get("id"),
            "name": client.get("name"),
            "status": client.get("status"),
            "scopes": ["read:companies", "write:companies"],
            "quota": {
                "requests_per_minute": qm,
                "requests_per_day": qd,
            },
            "usage": {
                "requests_last_minute": min_used,
                "requests_last_day": day_used,
            },
            "created_at": client.get("created_at"),
            "updated_at": client.get("updated_at"),
        }
    }

def list_companies(nif=None, name=None, city=None, record_status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, unicodedata, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0410000" if __import__("os").path.isdir("./environment_mix/0410000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm(s):
        if s is None:
            return ""
        if not isinstance(s, str):
            return ""
        s = s.strip().lower()
        s = unicodedata.normalize("NFKD", s)
        s = "".join(ch for ch in s if not unicodedata.combining(ch))
        s = re.sub(r"[^a-z0-9]+", " ", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.urandom(4).hex()}"

    def _pick_ambient_client(clients):
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        def _score(c):
            try:
                return (int(c.get("quota_requests_per_day") or 0), int(c.get("quota_requests_per_minute") or 0))
            except Exception:
                return (0, 0)
        active.sort(key=_score, reverse=True)
        return active[0]

    def _quota_check_and_log(requests, client, tool_name, input_nif, input_name, input_city):
        start = time.time()
        now = datetime.datetime.utcnow()
        day_ago = now - datetime.timedelta(days=1)
        min_ago = now - datetime.timedelta(minutes=1)

        cid = client.get("id") if client else None
        if not client or not cid:
            return False, _err("UNAUTHORIZED", "No authenticated active client available to serve this request."), None

        if client.get("status") != "active":
            latency = int((time.time() - start) * 1000)
            req_row = {
                "id": _gen_id("req"),
                "client_id": cid,
                "tool_name": tool_name,
                "input_nif": input_nif,
                "input_name": input_name,
                "input_city": input_city,
                "matched_company_id": None,
                "result_count": 0,
                "status": "rate_limited",
                "latency_ms": latency,
                "error_code": "CLIENT_NOT_ACTIVE",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            requests.append(req_row)
            _save("search_requests.json", requests)
            return False, _err("UNAUTHORIZED", "Client is not active.", client_status=client.get("status")), req_row

        try:
            qd = int(client.get("quota_requests_per_day"))
            qm = int(client.get("quota_requests_per_minute"))
        except Exception:
            qd, qm = 0, 0
        qd = max(qd, 0)
        qm = max(qm, 0)

        day_used = 0
        min_used = 0
        for r in requests:
            if not isinstance(r, dict) or r.get("client_id") != cid:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                day_used += 1
            if dt >= min_ago:
                min_used += 1

        if (qd != 0 and day_used >= qd) or (qm != 0 and min_used >= qm):
            latency = int((time.time() - start) * 1000)
            req_row = {
                "id": _gen_id("req"),
                "client_id": cid,
                "tool_name": tool_name,
                "input_nif": input_nif,
                "input_name": input_name,
                "input_city": input_city,
                "matched_company_id": None,
                "result_count": 0,
                "status": "rate_limited",
                "latency_ms": latency,
                "error_code": "QUOTA_EXCEEDED",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            requests.append(req_row)
            _save("search_requests.json", requests)
            return False, _err("QUOTA_EXCEEDED", "Request quota exceeded."), req_row

        return True, None, None

    clients = _load("api_clients.json")
    companies = _load("companies.json")
    requests = _load("search_requests.json")

    client = _pick_ambient_client(clients)
    ok, err_obj, _ = _quota_check_and_log(requests, client, "search_companies_by_name_and_city", nif, name, city)
    if not ok:
        return err_obj

    # Validate filters
    if nif is not None:
        if not isinstance(nif, str) or not re.fullmatch(r"^[0-9]{9}$", nif):
            # log invalid_input
            req_row = {
                "id": _gen_id("req"),
                "client_id": client["id"],
                "tool_name": "search_companies_by_name_and_city",
                "input_nif": nif if isinstance(nif, str) else None,
                "input_name": name if isinstance(name, str) else None,
                "input_city": city if isinstance(city, str) else None,
                "matched_company_id": None,
                "result_count": 0,
                "status": "invalid_input",
                "latency_ms": 0,
                "error_code": "INVALID_NIF",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            requests.append(req_row)
            _save("search_requests.json", requests)
            return _err("VALIDATION_ERROR", "nif must match ^[0-9]{9}$")

    if record_status is not None:
        if not isinstance(record_status, str) or record_status not in ("current", "deprecated", "deleted"):
            req_row = {
                "id": _gen_id("req"),
                "client_id": client["id"],
                "tool_name": "search_companies_by_name_and_city",
                "input_nif": nif if isinstance(nif, str) else None,
                "input_name": name if isinstance(name, str) else None,
                "input_city": city if isinstance(city, str) else None,
                "matched_company_id": None,
                "result_count": 0,
                "status": "invalid_input",
                "latency_ms": 0,
                "error_code": "INVALID_RECORD_STATUS",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            requests.append(req_row)
            _save("search_requests.json", requests)
            return _err("VALIDATION_ERROR", "record_status must be one of: current, deprecated, deleted")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        req_row = {
            "id": _gen_id("req"),
            "client_id": client["id"],
            "tool_name": "search_companies_by_name_and_city",
            "input_nif": nif if isinstance(nif, str) else None,
            "input_name": name if isinstance(name, str) else None,
            "input_city": city if isinstance(city, str) else None,
            "matched_company_id": None,
            "result_count": 0,
            "status": "invalid_input",
            "latency_ms": 0,
            "error_code": "INVALID_LIMIT",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        requests.append(req_row)
        _save("search_requests.json", requests)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    # Decode cursor (opaque)
    start_after_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            # expected format: "id:<company_id>"
            if not raw.startswith("id:"):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            start_after_id = raw[3:]
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    nf_name = _norm(name) if isinstance(name, str) and name.strip() else None
    nf_city = _norm(city) if isinstance(city, str) and city.strip() else None

    # Filter and sort deterministically by id
    rows = []
    seen_nifs = set()
    for c in companies:
        if not isinstance(c, dict):
            continue
        rs = c.get("record_status")
        if record_status is None:
            if rs == "deleted":
                continue
        else:
            if rs != record_status:
                continue

        cnif = c.get("nif")
        if isinstance(cnif, str):
            if cnif in seen_nifs:
                continue
            seen_nifs.add(cnif)

        if nif is not None and c.get("nif") != nif:
            continue

        if nf_name is not None:
            target = _norm(c.get("normalized_name") or c.get("legal_name") or "")
            if nf_name not in target:
                continue

        if nf_city is not None:
            target_city = _norm(c.get("city") or "")
            if nf_city != target_city:
                continue

        rows.append(c)

    rows.sort(key=lambda r: (r.get("id") or "", r.get("nif") or ""))

    if start_after_id:
        # find index strictly after id
        idx = 0
        for i, r in enumerate(rows):
            if r.get("id") == start_after_id:
                idx = i + 1
                break
        else:
            idx = 0
        rows_page = rows[idx: idx + limit]
        next_idx = idx + limit
    else:
        rows_page = rows[:limit]
        next_idx = limit

    has_more = next_idx < len(rows)
    next_cursor = None
    if has_more and rows_page:
        last_id = rows_page[-1].get("id")
        if last_id:
            next_cursor = base64.urlsafe_b64encode(f"id:{last_id}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Log request using closest enum tool_name: search_companies_by_name_and_city
    matched_company_id = rows_page[0].get("id") if rows_page else None
    req_row = {
        "id": _gen_id("req"),
        "client_id": client["id"],
        "tool_name": "search_companies_by_name_and_city",
        "input_nif": nif if isinstance(nif, str) else None,
        "input_name": name if isinstance(name, str) else None,
        "input_city": city if isinstance(city, str) else None,
        "matched_company_id": matched_company_id,
        "result_count": len(rows_page),
        "status": "ok" if rows_page or len(rows) == 0 else "ok",
        "latency_ms": 0,
        "error_code": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    requests.append(req_row)
    _save("search_requests.json", requests)

    return {
        "data": rows_page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "filters": {
            "nif": nif,
            "name": name,
            "city": city,
            "record_status": record_status,
        },
    }

def create_company(nif, legal_name, city, address=None, postal_code=None, company_type=None, is_accounting_company=None, active_status=None, record_status=None, source=None, last_verified_at=None, **_extra):
    import json, os, datetime, time, re, unicodedata, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0410000" if __import__("os").path.isdir("./environment_mix/0410000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _normalize(s):
        if s is None:
            return ""
        if not isinstance(s, str):
            s = str(s)
        s = s.strip().lower()
        s = unicodedata.normalize("NFKD", s)
        s = "".join(ch for ch in s if not unicodedata.combining(ch))
        s = re.sub(r"[^a-z0-9]+", " ", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(10)}"

    def _ensure_list(x):
        return x if isinstance(x, list) else ([] if x is None else [])

    def _pick_active_client(clients):
        active = [c for c in _ensure_list(clients) if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        def _q(c):
            try:
                return (int(c.get("quota_requests_per_day", 0)), int(c.get("quota_requests_per_minute", 0)))
            except Exception:
                return (0, 0)
        active.sort(key=_q, reverse=True)
        return active[0]

    def _parse_iso_z(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s = s.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt.replace(microsecond=0)
        except Exception:
            return None

    def _log_request(search_requests, client_id, status, result_count, matched_company_id=None, error_code=None, latency_ms=None):
        rid = _gen_id("nifc_req")
        row = {
            "id": rid,
            "client_id": client_id,
            "tool_name": "get_company",  # create_company isn't in schema enum; log under get_company to keep store consistent
            "input_nif": nif if isinstance(nif, str) else (None if nif is None else str(nif)),
            "input_name": legal_name if isinstance(legal_name, str) else (None if legal_name is None else str(legal_name)),
            "input_city": city if isinstance(city, str) else (None if city is None else str(city)),
            "matched_company_id": matched_company_id,
            "result_count": int(result_count) if isinstance(result_count, int) and result_count >= 0 else 0,
            "status": status,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, int) and latency_ms >= 0 else None,
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        search_requests.append(row)
        return row

    def _rate_limited(search_requests, client):
        cid = client.get("id")
        qd = client.get("quota_requests_per_day", 0)
        qm = client.get("quota_requests_per_minute", 0)
        try:
            qd = int(qd)
        except Exception:
            qd = 0
        try:
            qm = int(qm)
        except Exception:
            qm = 0
        if qd < 0 or qm < 0:
            return True, "QUOTA_CONFIG_INVALID"

        day_ago = now - datetime.timedelta(days=1)
        min_ago = now - datetime.timedelta(minutes=1)

        day_count = 0
        min_count = 0
        for r in _ensure_list(search_requests):
            if not isinstance(r, dict) or r.get("client_id") != cid:
                continue
            dt = _parse_iso_z(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_ago:
                day_count += 1
            if dt >= min_ago:
                min_count += 1

        if qm and min_count >= qm:
            return True, "quota_requests_per_minute"
        if qd and day_count >= qd:
            return True, "quota_requests_per_day"
        return False, None

    # Load datastore
    clients = _load("api_clients.json")
    companies = _load("companies.json")
    search_requests = _load("search_requests.json")

    client = _pick_active_client(clients)
    if client is None:
        return _err("UNAUTHORIZED", "No active API client available to serve this request.")

    # Validate inputs
    if not isinstance(nif, str) or not re.match(r"^[0-9]{9}$", nif):
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "invalid_input", 0, matched_company_id=None, error_code="invalid_nif", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "Invalid input: nif must match ^[0-9]{9}$.", field="nif")
    if not isinstance(legal_name, str) or not legal_name.strip():
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "invalid_input", 0, matched_company_id=None, error_code="legal_name_required", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "Invalid input: legal_name must be a non-empty string.", field="legal_name")
    if not isinstance(city, str) or not city.strip():
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "invalid_input", 0, matched_company_id=None, error_code="city_required", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "Invalid input: city must be a non-empty string.", field="city")

    if active_status is None:
        active_status = "unknown"
    if active_status not in ("active", "inactive", "unknown"):
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "invalid_input", 0, error_code="invalid_active_status", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "Invalid input: active_status must be one of 'active','inactive','unknown'.", field="active_status")

    if record_status is None:
        record_status = "current"
    if record_status not in ("current", "deprecated"):
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "invalid_input", 0, error_code="invalid_record_status", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "Invalid input: record_status must be 'current' or 'deprecated'.", field="record_status")

    if is_accounting_company is None:
        is_accounting_company = False
    if not isinstance(is_accounting_company, bool):
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "invalid_input", 0, error_code="invalid_is_accounting_company", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "Invalid input: is_accounting_company must be boolean.", field="is_accounting_company")

    if last_verified_at is not None:
        if not isinstance(last_verified_at, str) or _parse_iso_z(last_verified_at) is None:
            latency_ms = int((time.time() - t0) * 1000)
            _log_request(search_requests, client.get("id"), "invalid_input", 0, error_code="invalid_last_verified_at", latency_ms=latency_ms)
            _save("search_requests.json", search_requests)
            return _err("VALIDATION_ERROR", "Invalid input: last_verified_at must be RFC3339 date-time string.", field="last_verified_at")

    # Client status / quota enforcement
    if client.get("status") != "active":
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "rate_limited", 0, error_code="client_not_active", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("UNAUTHORIZED", "API client is not active.", client_id=client.get("id"), client_status=client.get("status"))

    limited, which = _rate_limited(search_requests, client)
    if limited:
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "rate_limited", 0, error_code=which, latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("QUOTA_EXCEEDED", "Quota exceeded.", client_id=client.get("id"), limit=which)

    # Enforce unique(nif) ONLY against non-deleted companies (business-rule in defect text)
    existing = None
    for c in _ensure_list(companies):
        if isinstance(c, dict) and c.get("nif") == nif:
            existing = c
            break

    if existing is not None and existing.get("record_status") != "deleted":
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "error", 0, matched_company_id=existing.get("id"), error_code="unique_nif", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err(
            "CONFLICT",
            "Conflict: unique(nif) violated; a non-deleted company with this NIF already exists.",
            rule="unique(nif)",
            company_id=existing.get("id"),
            existing_record_status=existing.get("record_status"),
        )

    # If an existing deleted company with same NIF exists, "revive" it (idempotent-ish create).
    if existing is not None and existing.get("record_status") == "deleted":
        # Legal transition: deleted -> [] (no transitions). Can't revive via lifecycle, so create new id but keep NIF uniqueness.
        # To avoid skew, keep deleted record but replace it with a new current record by changing its id? Never mutate PK.
        # Create a new record and keep deleted as history.
        pass

    normalized_name = _normalize(legal_name)
    if not normalized_name:
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(search_requests, client.get("id"), "invalid_input", 0, error_code="normalized_name_empty", latency_ms=latency_ms)
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "Invalid input: legal_name normalizes to empty.", rule="normalized_name != ''", field="legal_name")

    new_id = _gen_id("nifc_cmp")
    row = {
        "id": new_id,
        "nif": nif,
        "legal_name": legal_name.strip(),
        "normalized_name": normalized_name,
        "city": city.strip(),
        "address": address if address is None else str(address),
        "postal_code": postal_code if postal_code is None else str(postal_code),
        "company_type": company_type if company_type is None else str(company_type),
        "is_accounting_company": bool(is_accounting_company),
        "active_status": active_status,
        "record_status": record_status,
        "source": source if source is None else str(source),
        "last_verified_at": last_verified_at,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Persist mutation
    companies = _ensure_list(companies)
    companies.append(row)
    _save("companies.json", companies)

    latency_ms = int((time.time() - t0) * 1000)
    _log_request(search_requests, client.get("id"), "ok", 1, matched_company_id=new_id, latency_ms=latency_ms)
    _save("search_requests.json", search_requests)

    return {"company": row}

def update_company(nif, legal_name=None, city=None, address=None, postal_code=None, company_type=None, is_accounting_company=None, active_status=None, record_status=None, source=None, last_verified_at=None, **_extra):
    import json, os, datetime, re, time, unicodedata, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0410000" if __import__("os").path.isdir("./environment_mix/0410000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _normalize_text(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = unicodedata.normalize("NFKD", s)
        s2 = "".join(ch for ch in s2 if not unicodedata.combining(ch))
        s2 = s2.lower()
        s2 = re.sub(r"[^a-z0-9\s]", " ", s2)
        s2 = re.sub(r"\s+", " ", s2).strip()
        return s2

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            # accept Z or offset; store as ISO string
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                # treat naive as UTC
                return dt.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        except ValueError:
            return None

    # Load store
    clients = _load("api_clients.json")
    companies = _load("companies.json")
    reqs = _load("search_requests.json")

    # Resolve ambient authenticated client: pick an active client that can serve request (not rate limited).
    # Enforce rate/quota using search_requests logs for that client.
    def _rolling_counts(client_id):
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        day_ago = now_dt - datetime.timedelta(days=1)
        min_ago = now_dt - datetime.timedelta(minutes=1)
        day_cnt = 0
        min_cnt = 0
        for r in reqs:
            if r.get("client_id") != client_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                if ts.endswith("Z"):
                    rdt = datetime.datetime.fromisoformat(ts[:-1]).replace(tzinfo=datetime.timezone.utc)
                else:
                    rdt = datetime.datetime.fromisoformat(ts)
                    if rdt.tzinfo is None:
                        rdt = rdt.replace(tzinfo=datetime.timezone.utc)
                    else:
                        rdt = rdt.astimezone(datetime.timezone.utc)
            except ValueError:
                continue
            if rdt >= day_ago:
                day_cnt += 1
            if rdt >= min_ago:
                min_cnt += 1
        return day_cnt, min_cnt

    chosen_client = None
    for c in clients:
        if c.get("status") != "active":
            continue
        qd = c.get("quota_requests_per_day")
        qm = c.get("quota_requests_per_minute")
        if not isinstance(qd, int) or qd < 0 or not isinstance(qm, int) or qm < 0:
            continue
        day_cnt, min_cnt = _rolling_counts(c.get("id"))
        if (qd == 0 and day_cnt >= 0) or (qm == 0 and min_cnt >= 0):
            # quota 0 means cannot serve
            continue
        if day_cnt >= qd or min_cnt >= qm:
            continue
        chosen_client = c
        break

    # Pre-validate inputs (needed for logging invalid_input with nif)
    nif_ok = isinstance(nif, str) and re.fullmatch(r"^[0-9]{9}$", nif or "") is not None

    def _log_and_return(status, result_count, matched_company_id=None, error_obj=None):
        latency_ms = int(max(0, round((time.time() - t0) * 1000)))
        entry = {
            "id": "sr_" + uuid.uuid4().hex,
            "client_id": (chosen_client.get("id") if chosen_client else (clients[0].get("id") if clients else "unknown_client")),
            "tool_name": "get_company",  # closest available enum; schema doesn't include update_company
            "input_nif": nif if nif_ok else (nif if isinstance(nif, str) else None),
            "input_name": None,
            "input_city": None,
            "matched_company_id": matched_company_id,
            "result_count": int(result_count) if isinstance(result_count, int) and result_count >= 0 else 0,
            "status": status,
            "latency_ms": latency_ms,
            "error_code": (error_obj.get("error", {}).get("code") if isinstance(error_obj, dict) else None),
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(entry)
        _save("search_requests.json", reqs)
        return error_obj if error_obj is not None else {
            "company": None,
            "result_count": entry["result_count"],
            "status": status
        }

    # If no active client can serve due to quotas/status, still log and refuse.
    if chosen_client is None:
        # If there exists any non-active client, treat as UNAUTHORIZED; otherwise quota exceeded.
        any_active = any(c.get("status") == "active" for c in clients)
        code = "UNAUTHORIZED" if not any_active else "QUOTA_EXCEEDED"
        err = _err(code, "No authorized client available for this request (inactive or over quota).")
        return _log_and_return("rate_limited" if code in ("QUOTA_EXCEEDED", "RATE_LIMIT") else "error", 0, None, err)

    # Validate nif
    if not nif_ok:
        err = _err("VALIDATION_ERROR", "Invalid nif: must match ^[0-9]{9}$.")
        return _log_and_return("invalid_input", 0, None, err)

    # Validate optional fields
    if legal_name is not None and (not isinstance(legal_name, str) or len(legal_name.strip()) < 1):
        err = _err("VALIDATION_ERROR", "legal_name must be a non-empty string.")
        return _log_and_return("invalid_input", 0, None, err)
    if city is not None and (not isinstance(city, str) or len(city.strip()) < 1):
        err = _err("VALIDATION_ERROR", "city must be a non-empty string.")
        return _log_and_return("invalid_input", 0, None, err)
    for fld, val in [("address", address), ("postal_code", postal_code), ("company_type", company_type), ("source", source)]:
        if val is not None and not isinstance(val, str):
            err = _err("VALIDATION_ERROR", f"{fld} must be a string.")
            return _log_and_return("invalid_input", 0, None, err)
    if is_accounting_company is not None and not isinstance(is_accounting_company, bool):
        err = _err("VALIDATION_ERROR", "is_accounting_company must be a boolean.")
        return _log_and_return("invalid_input", 0, None, err)
    if active_status is not None and active_status not in ("active", "inactive", "unknown"):
        err = _err("VALIDATION_ERROR", "active_status must be one of: active, inactive, unknown.")
        return _log_and_return("invalid_input", 0, None, err)
    if record_status is not None and record_status not in ("current", "deprecated", "deleted"):
        err = _err("VALIDATION_ERROR", "record_status must be one of: current, deprecated, deleted.")
        return _log_and_return("invalid_input", 0, None, err)
    parsed_lva = None
    if last_verified_at is not None:
        parsed_lva = _parse_dt(last_verified_at)
        if parsed_lva is None:
            err = _err("VALIDATION_ERROR", "last_verified_at must be a valid RFC3339/ISO8601 date-time string.")
            return _log_and_return("invalid_input", 0, None, err)

    # Find company by nif, excluding deleted
    target = None
    for co in companies:
        if co.get("nif") == nif and co.get("record_status") != "deleted":
            target = co
            break
    if target is None:
        err = _err("NOT_FOUND", "Company not found for provided nif (or is deleted).")
        return _log_and_return("not_found", 0, None, err)

    # Enforce lifecycle transitions if record_status is being changed
    if record_status is not None:
        cur = target.get("record_status")
        allowed = {
            "current": {"deprecated", "deleted"},
            "deprecated": {"current", "deleted"},
            "deleted": set(),
        }
        if cur not in allowed:
            err = _err("VALIDATION_ERROR", "Company record_status is invalid in datastore.")
            return _log_and_return("error", 0, target.get("id"), err)
        if record_status != cur:
            if record_status not in allowed[cur]:
                err = _err("INVALID_TRANSITION", f"Illegal record_status transition: {cur} -> {record_status}.")
                return _log_and_return("invalid_input", 0, target.get("id"), err)
            target["record_status"] = record_status

    # Apply updates
    if legal_name is not None:
        target["legal_name"] = legal_name.strip()
        nn = _normalize_text(target["legal_name"])
        if not nn:
            err = _err("VALIDATION_ERROR", "normalized_name derived from legal_name must not be empty.")
            return _log_and_return("invalid_input", 0, target.get("id"), err)
        target["normalized_name"] = nn
    if city is not None:
        target["city"] = city.strip()
    if address is not None:
        target["address"] = address
    if postal_code is not None:
        target["postal_code"] = postal_code
    if company_type is not None:
        target["company_type"] = company_type
    if is_accounting_company is not None:
        target["is_accounting_company"] = is_accounting_company
    if active_status is not None:
        target["active_status"] = active_status
    if source is not None:
        target["source"] = source
    if last_verified_at is not None:
        target["last_verified_at"] = parsed_lva

    # Enforce uniqueness on companies.nif (should already hold, but validate)
    nif_dups = [co for co in companies if co.get("nif") == target.get("nif")]
    if len(nif_dups) > 1:
        err = _err("CONFLICT", "Uniqueness violation: duplicate company nif in datastore.")
        return _log_and_return("error", 0, target.get("id"), err)

    target["updated_at"] = now
    _save("companies.json", companies)

    # Log as ok (result_count=1)
    latency_ms = int(max(0, round((time.time() - t0) * 1000)))
    import uuid as _uuid
    reqs.append({
        "id": "sr_" + _uuid.uuid4().hex,
        "client_id": chosen_client.get("id"),
        "tool_name": "get_company",  # closest available enum
        "input_nif": nif,
        "input_name": None,
        "input_city": None,
        "matched_company_id": target.get("id"),
        "result_count": 1,
        "status": "ok",
        "latency_ms": latency_ms,
        "error_code": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("search_requests.json", reqs)

    return {
        "company": target,
        "updated": True
    }

def update_api_client_status(id, status, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0410000" if __import__("os").path.isdir("./environment_mix/0410000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    clients = _load("api_clients.json")
    reqs = _load("search_requests.json")

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        err = _err("VALIDATION_ERROR", "id must be a non-empty string.")
        return err
    if status not in ("active", "suspended", "deleted"):
        err = _err("VALIDATION_ERROR", "status must be one of: active, suspended, deleted.")
        return err

    # Find client
    client = None
    for c in clients:
        if c.get("id") == id:
            client = c
            break
    if client is None:
        return _err("NOT_FOUND", "API client not found.")

    cur = client.get("status")
    if cur == "deleted":
        return _err("CONFLICT", "Cannot transition from deleted.")

    allowed = {
        "active": {"suspended", "deleted"},
        "suspended": {"active", "deleted"},
        "deleted": set(),
    }
    if cur not in allowed:
        return _err("VALIDATION_ERROR", "Client status is invalid in datastore.")
    if status != cur and status not in allowed[cur]:
        return _err("VALIDATION_ERROR", f"Illegal status transition: {cur} -> {status}.")

    # Mutate
    if status != cur:
        client["status"] = status
        client["updated_at"] = now
        _save("api_clients.json", clients)
        changed = True
    else:
        # Idempotent: no change, but still "success" (effect is maintaining desired state)
        changed = False

    # Log request dynamics in search_requests (closest tool enum)
    # This endpoint isn't in schema enum; log as 'get_company' with no inputs.
    latency_ms = int(max(0, round((time.time() - t0) * 1000)))
    reqs.append({
        "id": "sr_" + uuid.uuid4().hex,
        "client_id": client.get("id"),
        "tool_name": "get_company",
        "input_nif": None,
        "input_name": None,
        "input_city": None,
        "matched_company_id": None,
        "result_count": 1,
        "status": "ok",
        "latency_ms": latency_ms,
        "error_code": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("search_requests.json", reqs)

    return {
        "client": client,
        "changed": changed
    }
